    public function __construct(private EntityManagerInterface $em) {}

    /** @throws ImportException */
    public function import(PriceFile $file): void
    {
        // resolve existing provider codes and model keys from DB
        $em->transactional(function () use ($file) {
            $providers = $this->em->getRepository(Provider::class)->findAll();
            map by code
            foreach ($file->getProviders() as $spec) {
                $p = $map[$spec->getCode()] ?? new Provider(code, name);
                $p->setName(...); $off = $spec->getOffPeak();
                $p->replaceOffPeak($off ? $off['windowStart'] : null, ...);
                $em->persist($p); $map[code] = $p;
            }
            $em->flush(); // ids needed for FKs

            // models: key providerCode|code → Model
            existing models: query all
            foreach specs:
                provider must be in $map (after upserting file providers, map contains file+DB) → if missing throw ImportException
                find or create Model($p->getId(), code); persist; index
            $em->flush();

            // prices
            existing price row map by modelId|validFromTimestamp
            foreach specs:
                model must be in index → else throw
                existing row: find by modelId and valid_from
                if exists && !sameContent → update rates/unit/currency
                if not exists → persist new PriceRow
            $em->flush();
        });
    }
}
```

